// ValidateX509Cert validates all fields in X509Cert according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateX509Cert(m *X509Cert) error {
	if m == nil {
		return nil
	}

	// Validate Base64 (assert_required)
	if m.Base64 == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "field Base64 is required")
	}

	// Validate Base64 (assert_base64)
	if m.Base64 != "" {
		if err := utils.ValidateAssertBase64(m.Base64); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field Base64 base64 validation failed")
		}
	}

	// Validate Id (default max size: 32768 bytes)
	if len(m.Id) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Id exceeds max size of 32768 bytes, got: %d", len(m.Id))
	}

	// Validate Base64 (default max size: 32768 bytes)
	if len(m.Base64) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Base64 exceeds max size of 32768 bytes, got: %d", len(m.Base64))
	}

	return nil
}

// ValidateX509CertPair validates all fields in X509CertPair according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateX509CertPair(m *X509CertPair) error {
	if m == nil {
		return nil
	}

	// No field validations defined
	return nil
}

// ValidateX509CertRequest validates all fields in X509CertRequest according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateX509CertRequest(m *X509CertRequest) error {
	if m == nil {
		return nil
	}

	// Validate Exp (assert_required: must be > 0)
	if m.Exp <= 0 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Exp is required and must be greater than zero")
	}

	// Validate Exp (assert_duration: POSITIVE)
	if m.Exp <= 0 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Exp must be positive (> 0), got: %d", m.Exp)
	}

	// Validate ExtKeyUsage (assert_max_items: 16)
	if len(m.ExtKeyUsage) > 16 {
		return protoerrors.NewErrMissingInvalidData(nil, "field ExtKeyUsage exceeds max items of 16, got: %d", len(m.ExtKeyUsage))
	}

	// Validate Issuer (assert_required)
	if m.Issuer == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "field Issuer is required")
	}

	// Validate Issuer (assert_min_length: 1)
	if len(m.Issuer) < 1 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Issuer must be at least 1 characters, got: %d", len(m.Issuer))
	}

	// Validate Issuer (default max size: 32768 bytes)
	if len(m.Issuer) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Issuer exceeds max size of 32768 bytes, got: %d", len(m.Issuer))
	}

	return nil
}

