// ============================================================
// Merge: X509Cert
// ============================================================
// MergeX509Cert fills zero-valued fields in dst from src.
func MergeX509Cert(dst, src *X509Cert) {
	if dst.Id == "" {
		dst.Id = src.Id
	}
	if dst.Base64 == "" {
		dst.Base64 = src.Base64
	}
}

// ============================================================
// Merge: X509CertPair
// ============================================================
// MergeX509CertPair fills zero-valued fields in dst from src.
func MergeX509CertPair(dst, src *X509CertPair) {
	if dst.Key == nil {
		dst.Key = src.Key
	}
	if dst.Cert == nil {
		dst.Cert = src.Cert
	} else if src.Cert != nil {
		MergeX509Cert(dst.Cert, src.Cert)
	}
}

// ============================================================
// Merge: X509CertRequest
// ============================================================
// MergeX509CertRequest fills zero-valued fields in dst from src.
func MergeX509CertRequest(dst, src *X509CertRequest) {
	if dst.Key == nil {
		dst.Key = src.Key
	}
	if dst.Exp == 0 {
		dst.Exp = src.Exp
	}
	if dst.Metadata == nil {
		dst.Metadata = src.Metadata
	}
	if dst.KeyUsage == 0 {
		dst.KeyUsage = src.KeyUsage
	}
	if len(dst.ExtKeyUsage) == 0 {
		dst.ExtKeyUsage = src.ExtKeyUsage
	}
	if dst.Issuer == "" {
		dst.Issuer = src.Issuer
	}
}
